INSERT IGNORE INTO `Article` (`id`, `title`, `slug`, `summary`, `content`, `imageUrl`, `status`, `publishedAt`, `createdAt`, `updatedAt`) VALUES (1, 'أهمية الفحوصات الدورية لأسنان الأطفال منذ سن مبكرة', 'pediatric-dental-checkups', 'تعرف على الأسباب العلمية التي تجعل زيارة طبيب الأسنان للأطفال في سن مبكرة خطوة حاسمة لضمان صحة فموية مستدامة ونمو سليم للأسنان الدائمة.', 'الكثير من الآباء يعتقدون أن الأسنان اللبنية ستسقط بكل الأحوال، لذلك لا داعي للعناية الفائقة بها. هذا الاعتقاد خاطئ تماماً من الناحية العلمية.\n\nالأسنان اللبنية تلعب دوراً حاسماً في حفظ المسافات للأسنان الدائمة. إذا تم خلع سن لبني مبكراً بسبب التسوس، فإن الأسنان المجاورة تميل لتغطية الفراغ، مما يؤدي إلى انطمار الأسنان الدائمة والحاجة لتقويم معقد مستقبلاً.\n\nكما أن الزيارات الدورية (كل 6 أشهر) تساعد في تطبيق الفلورايد الوقائي وسدادات الشقوق (Fissure Sealants) التي تحمي طواحن الأطفال من التسوس بنسبة تصل إلى 80%.', 'https://images.unsplash.com/photo-1606811841689-23dfddce3e95?auto=format&fit=crop&w=800&q=80', 'published', '2026-08-30 22:21:17', '2026-08-30 22:21:17', '2026-08-30 23:06:33');
INSERT IGNORE INTO `Article` (`id`, `title`, `slug`, `summary`, `content`, `imageUrl`, `status`, `publishedAt`, `createdAt`, `updatedAt`) VALUES (2, 'زراعة الأسنان: ثورة الطب الحديث في التعويضات السنية', 'dental-implants-revolution', 'تعتبر زراعة الأسنان الحل الأقرب للأسنان الطبيعية. نناقش في هذا المقال التقنيات الحديثة، نسبة النجاح، وكيفية الاندماج العظمي.', 'زراعة الأسنان ليست مجرد تعويض تجميلي، بل هي إجراء طبي حيوي لمنع ضمور عظم الفك. عندما يتم فقدان السن، يبدأ عظم الفك المحيط به بالذوبان تدريجياً بسبب غياب التحفيز الميكانيكي الناتج عن المضغ.\n\nالزرعات المصنوعة من التيتانيوم الخالص تتميز بخاصية فريدة تسمى (الاندماج العظمي - Osseointegration)، حيث تنمو الخلايا العظمية وتلتصق مباشرة بسطح التيتانيوم، مما يوفر ثباتاً مدى الحياة.\n\nتصل نسب نجاح زراعة الأسنان اليوم إلى أكثر من 98%، وتعتبر الخيار الأول طبياً للتعويض عن الأسنان المفقودة.', '/images/blog/1.jpg', 'published', '2026-08-29 22:21:17', '2026-08-30 22:21:17', '2026-08-30 23:06:33');
INSERT IGNORE INTO `Article` (`id`, `title`, `slug`, `summary`, `content`, `imageUrl`, `status`, `publishedAt`, `createdAt`, `updatedAt`) VALUES (3, 'العلاقة الوثيقة بين السكري وصحة اللثة', 'diabetes-and-gum-disease', 'هناك علاقة ثنائية الاتجاه بين مرض السكري وأمراض اللثة. اكتشف كيف يؤثر كل منهما على الآخر وكيف تحمي نفسك.', 'أثبتت الدراسات العلمية أن العلاقة بين التهاب اللثة المزمن ومرض السكري هي علاقة (ثنائية الاتجاه). \n\nمرضى السكري غير المنتظم يعانون من ضعف في التروية الدموية الدقيقة وبطء في التئام الجروح، مما يجعل لثتهم بيئة خصبة للبكتيريا اللاهوائية التي تسبب تآكل عظم الفك.\n\nمن جهة أخرى، الالتهاب المزمن في اللثة يرفع من مستويات السيتوكينات الالتهابية في الدم، مما يزيد من مقاومة الخلايا للإنسولين ويجعل السيطرة على مستوى السكر في الدم أمراً بالغ الصعوبة.\n\nلذا، يُنصح مرضى السكري بزيارة طبيب الأسنان كل 3 إلى 4 أشهر لتنظيف الجيوب اللثوية.', '/images/blog/2.jpg', 'published', '2026-08-28 22:21:17', '2026-08-30 22:21:17', '2026-08-30 23:06:33');
INSERT IGNORE INTO `Article` (`id`, `title`, `slug`, `summary`, `content`, `imageUrl`, `status`, `publishedAt`, `createdAt`, `updatedAt`) VALUES (4, 'تبييض الأسنان بالليزر: خرافات وحقائق علمية', 'laser-teeth-whitening-facts', 'هل تبييض الأسنان يضر بطبقة المينا؟ ما هو دور الليزر فعلياً؟ مقال علمي يوضح كل الحقائق حول التبييض.', 'يعتقد الكثيرون أن تبييض الأسنان يزيل طبقة من سطح السن، وهذا غير صحيح علمياً. مادة التبييض (بيروكسيد الهيدروجين أو بيروكسيد الكارباميد) تتغلغل داخل مسام المينا لتتفاعل مع جزيئات التصبغات وتكسر روابطها الكيميائية، مما يفتح لون السن دون المساس بهيكله.\n\nأما بالنسبة لـ (الليزر) أو أجهزة الضوء الأزرق المستخدمة في العيادات، فدورها هو فقط تسريع التفاعل الكيميائي لمادة التبييض لتقليل وقت الجلسة، ولا تقوم بالتبييض بحد ذاتها.\n\nالآثار الجانبية الوحيدة للتبييض هي حساسية مؤقتة للأسنان تزول خلال 48 ساعة، ويمكن السيطرة عليها بمعاجين الفلورايد.', 'https://images.unsplash.com/photo-1579684385127-1ef15d508118?auto=format&fit=crop&w=800&q=80', 'published', '2026-08-27 22:21:17', '2026-08-30 22:21:17', '2026-08-30 23:06:33');
INSERT IGNORE INTO `Doctor` (`id`, `nameAr`, `nameEn`, `titleAr`, `titleEn`, `slug`, `image`, `shortBio`, `qualifications`, `specialties`, `isActive`, `createdAt`, `updatedAt`) VALUES (5, 'د. وليد', 'Dr. Waleed', 'طبيب أسنان', 'Dentist', 'dr-waleed', '/images/doctors/waleed.jpg', 'خبرة واسعة في علاجات الأسنان وتجميلها.', '["بكالوريوس طب وجراحة الفم والأسنان"]', '["طب الأسنان العام","تجميل الأسنان"]', 1, '2026-08-30 18:50:01', '2026-08-30 18:50:01');
INSERT IGNORE INTO `Doctor` (`id`, `nameAr`, `nameEn`, `titleAr`, `titleEn`, `slug`, `image`, `shortBio`, `qualifications`, `specialties`, `isActive`, `createdAt`, `updatedAt`) VALUES (6, 'د. منتصر', 'Dr. Montaser', 'استشاري طب الأسنان', 'Dental Consultant', 'dr-montaser', '/images/doctors/montaser.jpg', 'متخصص في الحالات المعقدة وزراعة الأسنان بخبرة تزيد عن 20 عاماً.', '["البورد في زراعة الأسنان","بكالوريوس طب وجراحة الفم والأسنان"]', '["زراعة الأسنان","جراحة الفم"]', 1, '2026-08-30 18:50:01', '2026-08-30 18:50:01');
INSERT IGNORE INTO `Doctor` (`id`, `nameAr`, `nameEn`, `titleAr`, `titleEn`, `slug`, `image`, `shortBio`, `qualifications`, `specialties`, `isActive`, `createdAt`, `updatedAt`) VALUES (7, 'د. عمار', 'Dr. Ammar', 'أخصائي تقويم الأسنان', 'Orthodontist', 'dr-ammar', '/images/doctors/ammar.jpg', 'متخصص في تقويم الأسنان للأطفال والبالغين باستخدام أحدث التقنيات.', '["ماجستير في تقويم الأسنان","بكالوريوس طب الأسنان"]', '["تقويم الأسنان الشفاف","التقويم المعدني"]', 1, '2026-08-30 18:50:01', '2026-08-30 18:50:01');
INSERT IGNORE INTO `Doctor` (`id`, `nameAr`, `nameEn`, `titleAr`, `titleEn`, `slug`, `image`, `shortBio`, `qualifications`, `specialties`, `isActive`, `createdAt`, `updatedAt`) VALUES (8, 'د. دعاء', 'Dr. Doaa', 'أخصائية تجميل الأسنان', 'Cosmetic Dentist', 'dr-doaa', '/images/doctors/doaa.jpg', 'شغف كبير في تجميل الأسنان وتصميم الابتسامة (ابتسامة هوليود).', '["دبلوم في تجميل الأسنان","بكالوريوس طب الأسنان"]', '["تصميم الابتسامة","الفينير واللومينير"]', 1, '2026-08-30 18:50:01', '2026-08-30 18:50:01');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (1, 'كم تستغرق عملية زراعة الأسنان؟', 'تعتمد المدة على الحالة الفردية لكل مريض. عادةً تتضمن زراعة الأسنان جلستين رئيسيتين: الأولى لزرع التيتانيوم في الفك، وبعد فترة التكامل التي تمتد من 3 إلى 6 أشهر حسب كثافة العظام، تُركَّب التاج النهائي. يقوم طبيبنا بتحديد خطة علاجية مخصصة بعد الفحص الشامل.', 1, 1, '2026-08-30 12:20:36', '2026-08-30 12:20:36');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (2, 'هل عملية زراعة الأسنان مؤلمة؟', 'تُجرى عملية الزراعة تحت تأثير التخدير الموضعي، لذا لا يشعر المريض بالألم أثناء الإجراء. قد يحدث بعض الانزعاج والتورم البسيط في الأيام الأولى بعد الجراحة، وهو أمر طبيعي ويمكن التحكم فيه بمسكنات الألم الموصوفة.', 2, 1, '2026-08-30 12:20:36', '2026-08-30 12:20:36');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (3, 'كم تدوم تركيبات الزيركون؟', 'تتميز تركيبات الزيركون بمتانة عالية جداً، ويمكن أن تدوم 15 سنة أو أكثر مع العناية الجيدة. تشمل العناية: الفرشاة اليومية والخيط الطبي ومعجون الأسنان المناسب، إلى جانب الزيارات الدورية للعيادة للفحص والتنظيف.', 3, 1, '2026-08-30 12:20:36', '2026-08-30 12:20:36');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (4, 'ما الفرق بين فينير إيماكس والدايركت فينير؟', 'فينير إيماكس هو قشرة خزفية تُصنع في مختبر متخصص وتوفر نتائج جمالية أكثر دقة وديمومة أطول. أما الدايركت فينير فيُطبَّق مباشرة في العيادة بمادة الكومبوزيت في جلسة واحدة وبتكلفة أقل، مناسب للحالات التي تحتاج نتيجة سريعة.', 4, 1, '2026-08-30 12:20:36', '2026-08-30 12:20:36');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (5, 'كم مرة يجب تبييض الأسنان؟', 'يوصي أطباؤنا بالتبييض الاحترافي مرة أو مرتين في السنة حسب طبيعة الحالة ومدى تعرض الأسنان لعوامل التصبغ. يُنصح بتجنب القهوة والشاي والتدخين في الساعات الأولى بعد الجلسة للحفاظ على النتيجة أطول فترة ممكنة.', 5, 1, '2026-08-30 12:20:36', '2026-08-30 12:20:36');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (6, 'هل تبييض الأسنان آمن على المدى البعيد؟', 'نعم، تبييض الأسنان الاحترافي الذي يُجرى في العيادة تحت إشراف طبيب مؤهل آمن تماماً. نستخدم مواد معتمدة طبياً بتركيزات مدروسة تضمن الفعالية دون الإضرار بمينا الأسنان أو أنسجة اللثة.', 6, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (7, 'من يناسبه سناب أون سمايل؟', 'سناب أون سمايل مناسب لمن يريد تحسيناً جمالياً سريعاً لمناسبة خاصة، أو لمن لا يرغب في إجراء علاجي دائم. يُنصح أيضاً باستخدامه كخطوة أولى لتجربة الشكل المنشود قبل الالتزام بالفينير أو الزيركون الدائم.', 7, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (8, 'متى أحتاج إلى علاج جذور الأسنان؟', 'تحتاج إلى علاج الجذر (حشو العصب) عند الشعور بألم حاد ومستمر في السن، حساسية شديدة للحرارة لا تختفي، تورم أو ناسور في اللثة قرب السن، أو عند ظهور تغيّر داكن في لون السن. التشخيص المبكر يزيد من فرص إنقاذ السن.', 8, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (9, 'كم مرة يجب زيارة طبيب الأسنان سنوياً؟', 'يُوصى بزيارة طبيب الأسنان مرتين في السنة (كل 6 أشهر) للفحص الدوري والتنظيف الاحترافي. الكشف المبكر عن أي مشكلة يوفر عليك العلاجات المعقدة والمكلفة لاحقاً.', 9, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (10, 'هل الزراعة الأمريكية والألمانية والإيطالية تختلف فعلاً؟', 'نعم، تختلف في بعض تفاصيل التصميم والمواد المستخدمة، لكن جميعها تلتزم بأعلى معايير الجودة الدولية. الاختيار بين الأنواع يعتمد على حالة عظام الفك وتوقعات المريض وتوصية الطبيب بعد الفحص الدقيق.', 10, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (11, 'هل أسنان الأطفال تحتاج زيارة طبيب أسنان متخصص؟', 'نعم، يُوصى ببدء زيارات طبيب الأسنان منذ ظهور أول سن لدى الطفل، وليس لاحقاً. يساعد ذلك في الوقاية المبكرة وتعويد الطفل على جو العيادة. لدى مجمعنا أطباء متخصصون في التعامل مع الأطفال بأسلوب مريح وودود.', 11, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (12, 'هل الحشوات التجميلية البيضاء بنفس متانة الحشوات الفضية؟', 'الحشوات التجميلية الحديثة من مادة الكومبوزيت عالي الجودة تقدم متانة ممتازة في الأسنان الأمامية والخلفية، وقد تطورت كثيراً في السنوات الأخيرة لتقاوم ضغط المضغ. تميل الحشوات الفضية للمتانة أكثر قليلاً في الضروس الخلفية الكبيرة، لكن الكومبوزيت تبقى الخيار الأجمل والأكثر شيوعاً.', 12, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (13, 'ما هي ابتسامة كلافيل ثلاثية الأبعاد؟', 'ابتسامة كلافيل ثلاثية الأبعاد هي نظام متكامل يجمع بين التصميم الرقمي الحاسوبي والتقنيات الحديثة لتصميم ابتسامتك وعرض النتيجة المتوقعة عليك قبل البدء في أي علاج. يمنحك تصوراً واضحاً للشكل النهائي ويضمن رضاك التام.', 13, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (14, 'هل يمكن زراعة الأسنان لمرضى السكري؟', 'يمكن إجراء زراعة الأسنان لمرضى السكري إذا كان مستوى السكر في الدم تحت السيطرة الجيدة. يُجري طبيبنا تقييماً شاملاً لحالتك الصحية قبل التوصية بأي إجراء، والتنسيق مع طبيبك المعالج إذا لزم الأمر.', 14, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
INSERT IGNORE INTO `Faq` (`id`, `question`, `answer`, `order`, `isActive`, `createdAt`, `updatedAt`) VALUES (15, 'كيف أحافظ على نظافة الأسنان المزروعة؟', 'تُعامَل الأسنان المزروعة مثل الأسنان الطبيعية: فرشاة ناعمة مرتين يومياً، خيط طبي أو رأس مائي، غسول فم مضاد للبكتيريا، وزيارة دورية للعيادة كل 6 أشهر. تجنب قضم الأشياء الصلبة والتدخين للحفاظ على الزرعة لأطول فترة ممكنة.', 15, 1, '2026-08-30 12:20:37', '2026-08-30 12:20:37');
